+/// Order edges by their minimum integer X coordinate. An edge can only meet
+/// following edges whose minimum X is no greater than its maximum X. This
+/// rejects distant pairs before the exact integer intersection predicate;
+/// touching bounds remain candidates. Adjacency uses the original ring order.
+fn ring_self_intersects(path: &Path64) -> bool {
+    let mut segments: Vec<_> = edges(path).enumerate().collect();
+    // Avoid sorting overhead for the common small rectangle/bracket contours.
+    let sweep = segments.len() > 32;
+    if sweep {
+        segments.sort_unstable_by_key(|&(index, (a, b))| (a.x.min(b.x), index));
+    }
+    for (position, &(i, (a, b))) in segments.iter().enumerate() {
+        for &(j, (c, d)) in segments.iter().skip(position + 1) {
+            if sweep && c.x.min(d.x) > a.x.max(b.x) {
+                break;
+            }
+            if i.abs_diff(j) == 1 || i.abs_diff(j) == path.len() - 1 {
+                continue;
+            }
+            if segments_touch(a, b, c, d) {
+                return true;
+            }
+        }
+    }
+    false
+}
